#!/usr/bin/env node
/**
 * Assemble the web seller/admin workspace (web/) for the Android app, under www/seller/.
 *
 * Owner: Claude 2 (see docs/WORKFLOW/CLAUDE_TEAM_WORKSPACE.md, task X2-01/X2-02).
 *
 * Why this exists: web/ in git does not contain the shared files the Cloudflare build copies in
 * (config.js, supa.js, icons.js, art.js, geo.js, turnstile.js, theme.js, tokens.css, fonts.css, fonts/).
 * This script does that same copy, then makes the copy safe to serve from /seller/ inside the app:
 *   - only web/index.html is rewritten (the only file with root-absolute /assets and /favicon paths);
 *   - the environment comes from the CI-stamped build (window.BUILD.branch), never from the page host;
 *   - for any build that is not `main` the live Supabase project is removed from the bundle entirely (issue #34);
 *   - the seller shell shares the shopper app's stored session (en_sess).
 * It does NOT change web/ and it does NOT link the seller shell from the shopper UI. Route prefixing (X2-03),
 * the ownership gate and the Shop / My Store switch (X2-05) come later.
 *
 * Usage: BUILD_BRANCH=<branch> node tools/assemble-seller-bundle.mjs [--out www/seller]
 *        (BUILD_BRANCH defaults to "local", which is treated as staging.)
 */
import fs from "node:fs";
import path from "node:path";

const args = process.argv.slice(2);
const outArg = args.indexOf("--out");
export const OUT = outArg >= 0 ? args[outArg + 1] : "www/seller";
export const PREFIX = "/seller";
export const LIVE_REF = "zpgasfweaixwsktlueje";
export const STAGING_REF = "vjiadqygpyebpisxslbx";
const branch = process.env.BUILD_BRANCH || "local";
const isMain = branch === "main";

const must = (p) => { if (!fs.existsSync(p)) throw new Error("Required source is missing: " + p); };
const copyFile = (from, to) => { must(from); fs.mkdirSync(path.dirname(to), { recursive: true }); fs.copyFileSync(from, to); };

function assemble() {
  must("web/index.html");
  fs.rmSync(OUT, { recursive: true, force: true });
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  // 1. The web tree, minus files that only mean something on Cloudflare Pages.
  const skip = new Set(["_redirects", "_headers", "README.md"]);
  fs.cpSync("web", OUT, { recursive: true, filter: (p) => !skip.has(path.basename(p)) });
  // 2. The shared files the Cloudflare workflow copies in (same list as cloudflare-pages-package.yml).
  for (const f of ["tokens.css", "fonts.css"]) copyFile(path.join("css", f), path.join(OUT, "assets/css", f));
  must("fonts");
  fs.cpSync("fonts", path.join(OUT, "assets/fonts"), { recursive: true });
  copyFile("js/theme.js", path.join(OUT, "assets/js/theme.js"));
  const shared = fs.readdirSync("shared", { withFileTypes: true }).filter((e) => e.isFile() && e.name.endsWith(".js"));
  if (!shared.length) throw new Error("shared/*.js is empty");
  for (const e of shared) copyFile(path.join("shared", e.name), path.join(OUT, "assets/js", e.name));

  // 3. Environment. A non-main bundle cannot reach the live project because the live project is not in it.
  const cfgPath = path.join(OUT, "assets/js/config.js");
  let cfg = fs.readFileSync(cfgPath, "utf8");
  if (!isMain) {
    const live = /var LIVE=\{[^}]*\};/;
    if (!live.test(cfg)) throw new Error("Could not find the LIVE block in shared/config.js to remove");
    cfg = cfg.replace(live, "var LIVE=null; /* removed: this bundle was built from a non-main branch */");
    cfg = cfg.split(LIVE_REF).join("(live project ref removed)"); // the header comment names it too
    if (cfg.includes(LIVE_REF)) throw new Error("Live project reference is still present after removal");
  }
  fs.writeFileSync(cfgPath, cfg);

  // 4. Native bootstrap: runs after the stamped /js/build.js and before config.js.
  fs.writeFileSync(path.join(OUT, "native-env.js"),
    "/* Generated by tools/assemble-seller-bundle.mjs. Do not edit. */\n" +
    "(function(){var b=window.BUILD||{};\n" +
    "  window.EV_NATIVE_SELLER=true;            /* ds-app.js turns the phone shell on and adds the Shop entry */\n" +
    "  window.EV_SESSION_KEY=\"en_sess\";          /* the shopper app's key: one session for both shells */\n" +
    "  window.EV_BASE=\"" + PREFIX + "\";             /* path prefix core.js removes when reading and adds when writing addresses */\n" +
    "  window.EV_ROUTE=\"hash\";                /* the route lives after the #, so a reload never depends on the app's local server fallback */\n" +
    "  window.EV_ENV=b.branch===\"main\"?\"live\":\"staging\"; /* unknown or missing build means staging */\n" +
    "})();\n");

  // 5. index.html: asset paths under /seller, bootstrap scripts before config.js.
  const htmlPath = path.join(OUT, "index.html");
  let html = fs.readFileSync(htmlPath, "utf8");
  html = html.replace(/(["'(])\/assets\//g, "$1" + PREFIX + "/assets/")
             .replace(/(["'(])\/favicon\.svg/g, "$1" + PREFIX + "/favicon.svg");
  const cfgTag = '<script src="' + PREFIX + '/assets/js/config.js"></script>';
  if (!html.includes(cfgTag)) throw new Error("index.html does not load config.js as expected");
  html = html.replace(cfgTag, '<script src="/js/build.js"></script>\n<script src="' + PREFIX + '/native-env.js"></script>\n' + cfgTag);
  fs.writeFileSync(htmlPath, html);
  return { branch, isMain, out: OUT };
}

if (import.meta.url === "file://" + process.argv[1] || process.argv[1]?.endsWith("assemble-seller-bundle.mjs")) {
  const r = assemble();
  console.log("Assembled seller bundle at " + r.out + " (branch " + r.branch + ", " + (r.isMain ? "live-capable" : "staging only") + "). Not linked from the shopper UI yet.");
}
